// ---------------------------------------------------------------------------
// DA Form 2408-20 (Oil Analysis Log) — coordinate-fill path.
//
// Blank DA Form 2408-20 template, base64-encoded, embedded so this page works
// as a single offline file with no server and no external PDF fetch.
// Derived from the form's own (blank) AcroForm field positions, then flattened
// — i.e. treated as a generic non-fillable PDF and filled by drawing text at
// those coordinates, which is the same approach PDF-gen uses for PDFs that
// never had fillable fields to begin with.
// ---------------------------------------------------------------------------
const BLANK_TEMPLATE_B64 = "";

// ---------------------------------------------------------------------------
// Field map: page index (0 = front, 1 = back), coordinates in PDF points
// (origin bottom-left), lifted from the form's own field positions.
// ---------------------------------------------------------------------------
const HEADER_FIELDS = {
  page:                        { page: 0, x: 424.2, y: 762, w: 29.4,  size: 9 },
  pageOf:                      { page: 0, x: 468,   y: 762, w: 28.2,  size: 9 },
  endItemNomenclature:         { page: 0, x: 33,    y: 715, w: 128,   size: 8 },
  endItemMakeOrType:           { page: 0, x: 33,    y: 691, w: 128,   size: 8 },
  endItemSerialNumber:         { page: 0, x: 33,    y: 667, w: 128,   size: 8 },
  sampleFrequency:             { page: 0, x: 169,   y: 695, w: 51,    size: 8 },
  componentNomenclatureType:   { page: 0, x: 227,   y: 715, w: 350,   size: 8 },
  componentSerialNumber:       { page: 0, x: 227,   y: 691, w: 172,   size: 8 },
  componentTimeSinceNewOverhaul:{ page: 0, x: 227,  y: 667, w: 172,   size: 8 },
  acftHrsLastOilChange:        { page: 0, x: 407,   y: 691, w: 172,   size: 8 },
  acftHrsInstalled:            { page: 0, x: 407,   y: 667, w: 172,   size: 8 },
  remarks:                     { page: 1, x: 33,    y: 490, w: 546,   size: 8, wrap: true, lineHeight: 11 },
};

// column x / width shared by both pages' row grids
const ROW_COLS = [
  { key: "dateSampleSubmitted", x: 30.4,  w: 55.1 },
  { key: "hoursEndItem",        x: 88.0,  w: 62.3 },
  { key: "hoursComponent",      x: 152.8, w: 62.3 },
  { key: "hoursLastOilChange",  x: 217.6, w: 62.3 },
  { key: "reasonForSample",     x: 282.4, w: 47.9 },
  { key: "results",             x: 332.8, w: 119.9 },
  { key: "resultsDate",         x: 455.2, w: 62.3 },
  { key: "resultsPid",          x: 520.0, w: 62.3 },
];

// per-row baseline y, front page (12 rows) then back page (8 rows) — 20 total per copy
const PAGE1_ROW_Y = [578.0, 555.4, 532.6, 509.3, 487.0, 464.5, 440.3, 417.4, 394.6, 371.3, 347.9, 325.5];
const PAGE2_ROW_Y = [675.0, 652.8, 630.0, 607.8, 585.5, 562.8, 540.0, 517.8];
const ROWS_PER_COPY = PAGE1_ROW_Y.length + PAGE2_ROW_Y.length; // 20

function rowSlots() {
  const slots = [];
  PAGE1_ROW_Y.forEach(y => slots.push({ page: 0, y }));
  PAGE2_ROW_Y.forEach(y => slots.push({ page: 1, y }));
  return slots;
}

function emptyRow2408_20() {
  return {
    id: uid(),
    dateSampleSubmitted: "", hoursEndItem: "", hoursComponent: "", hoursLastOilChange: "",
    reasonForSample: "", results: "", resultsDate: "", resultsPid: "",
  };
}

function emptyForm2408_20() {
  return {
    id: uid(),
    header: {
      endItemNomenclature: "", endItemMakeOrType: "", endItemSerialNumber: "",
      sampleFrequency: "",
      componentNomenclatureType: "", componentSerialNumber: "", componentTimeSinceNewOverhaul: "",
      acftHrsLastOilChange: "", acftHrsInstalled: "",
      remarks: "",
    },
    rows: [emptyRow2408_20()],
  };
}

function cloneForm2408_20(form) {
  return {
    id: uid(),
    header: { ...form.header },
    rows: form.rows.map(r => ({ ...r, id: uid() })),
  };
}

// ---------------------------------------------------------------------------
// Fill engine: draws text at the mapped coordinates onto copies of the blank
// template. Rows beyond ROWS_PER_COPY spill onto additional copies, all
// stamped with the same header data — this is a rendering-time computation
// only; nothing about how the data is stored needs to change as rows grow.
// ---------------------------------------------------------------------------
async function buildFilledPdf(form) {
  const { PDFDocument, StandardFonts, rgb } = PDFLib;
  const templateBytes = b64ToBytes(BLANK_TEMPLATE_B64);
  const templateDoc = await PDFDocument.load(templateBytes);

  const outDoc = await PDFDocument.create();
  const font = await outDoc.embedFont(StandardFonts.Helvetica);

  const rows = form.rows;
  const totalCopies = Math.max(1, Math.ceil(rows.length / ROWS_PER_COPY));
  const slots = rowSlots();

  for (let copyIndex = 0; copyIndex < totalCopies; copyIndex++) {
    const [p0, p1] = await outDoc.copyPages(templateDoc, [0, 1]);
    outDoc.addPage(p0);
    outDoc.addPage(p1);
    const pages = [p0, p1];

    const drawField = (spec, value) => {
      if (!value) return;
      const page = pages[spec.page];
      if (spec.wrap) {
        page.drawText(String(value), {
          x: spec.x, y: spec.y, size: spec.size, font,
          maxWidth: spec.w, lineHeight: spec.lineHeight || spec.size + 3,
          color: rgb(0, 0, 0),
        });
      } else {
        page.drawText(String(value), { x: spec.x, y: spec.y, size: spec.size, font, color: rgb(0, 0, 0) });
      }
    };

    // header (computed Page/Of + shared header fields, same on every copy)
    drawField(HEADER_FIELDS.page, String(copyIndex + 1));
    drawField(HEADER_FIELDS.pageOf, String(totalCopies));
    for (const key of Object.keys(form.header)) {
      if (key === "remarks" && copyIndex > 0) continue; // remarks lives on page 2 of copy 1 only
      if (HEADER_FIELDS[key]) drawField(HEADER_FIELDS[key], form.header[key]);
    }

    // this copy's slice of rows
    const start = copyIndex * ROWS_PER_COPY;
    const chunk = rows.slice(start, start + ROWS_PER_COPY);
    chunk.forEach((row, i) => {
      const slot = slots[i];
      for (const col of ROW_COLS) {
        const page = pages[slot.page];
        const value = row[col.key];
        if (!value) continue;
        page.drawText(String(value), {
          x: col.x + 2, y: slot.y + 6, size: 7, font,
          maxWidth: col.w - 4, lineHeight: 8.5, color: rgb(0, 0, 0),
        });
      }
    });
  }

  return outDoc.save();
}
